/** selectAccessiblePrivateFolder */
SELECT
    folder_id, folder_name, create_user_id, create_time, folder_type, resource_scope_user_id, resource_owner_id, access_policy, parent_folder_id, uuid
FROM
    folder_tb



            uuid = #{folderUuid}


            folder_id = #{folderId}


AND
    resource_scope_user_id = #{userId}
AND
    folder_type = #{folderType}
AND
    status = #{status}

/** selectPrivateEntryFolderByUserId */
SELECT
folder_id, folder_name, create_user_id, create_time, folder_type, resource_scope_user_id, resource_owner_id, access_policy, parent_folder_id, uuid
FROM
folder_tb

    WHERE


            uuid = #{folderUuid}


            folder_id = #{folderId}


    AND
        EXISTS(
            SELECT 1 FROM rel_user_team_tb rel
            JOIN team_tb t on rel.team_id = t.team_id
            WHERE rel.user_id = #{userId}
            AND rel.team_id = folder.resource_scope_team_id


                    AND t.uuid = #{teamUuid}


                    AND rel.team_id = #{teamId}


        )
    AND
    folder_type = #{folderType}
    AND
    status = #{status}

SELECT folder.uuid, folder.folder_name, folder.folder_type, folder.render_sequence, parent.uuid AS parent_folder_uuid, folder.status, (SELECT EXISTS(SELECT 1 from folder_tb where parent_folder_id = folder.folder_id)) as hasChild FROM folder_tb folder INNER JOIN folder_tb parent ON folder.parent_folder_id = parent.folder_id AND parent.folder_id = #{parentFolderId}
CROSS JOIN ( SELECT folder_id, COALESCE(render_sequence, 2147483647) AS cursor_render_sequence FROM folder_tb WHERE uuid = #{nextFolderUuid} ) criteria
AND folder.resource_scope_user_id = #{userId} AND folder.folder_type = #{folderType} AND folder.status = #{status}
AND ( COALESCE(folder.render_sequence, 2147483647) > criteria.cursor_render_sequence OR ( COALESCE(folder.render_sequence, 2147483647) = criteria.cursor_render_sequence AND folder.folder_id >= criteria.folder_id ) )
ORDER BY COALESCE(folder.render_sequence, 2147483647) ASC, folder.folder_id ASC LIMIT #{limit}

SELECT folder.uuid FROM folder_tb folder LEFT JOIN folder_tb parent ON folder.parent_folder_id = parent.folder_id AND parent.folder_id = #{parentFolderId}
CROSS JOIN ( SELECT folder_id, COALESCE(render_sequence, 2147483647) AS cursor_render_sequence FROM folder_tb WHERE uuid = #{lastFolderUuid} ) criteria
AND folder.resource_scope_user_id = #{userId} AND folder.folder_type = #{folderType} AND folder.status = #{status}
AND ( COALESCE(folder.render_sequence, 2147483647) > criteria.cursor_render_sequence OR ( COALESCE(folder.render_sequence, 2147483647) = criteria.cursor_render_sequence AND folder.folder_id > criteria.folder_id ) )
ORDER BY COALESCE(folder.render_sequence, 2147483647) ASC, folder.folder_id ASC LIMIT 1

SELECT folder.uuid, folder.folder_name, folder.folder_type, folder.render_sequence, parent.uuid AS parent_folder_uuid, folder.status, (SELECT EXISTS(SELECT 1 from folder_tb where parent_folder_id = folder.uuid)) as hasChild FROM folder_tb folder LEFT JOIN folder_tb parent ON folder.parent_folder_id = parent.folder_id
CROSS JOIN ( SELECT folder_id, COALESCE(render_sequence, 2147483647) AS cursor_render_sequence FROM folder_tb WHERE uuid = #{nextFolderUuid} ) criteria
parent.uuid = #{parentFolderUuid} AND resource_scope_team_id = (SELECT team_id from team_tb
uuid = #{teamUuid}
team_id = #{teamId}
) AND folder_type = #{folderType} AND folder.status = #{status}
AND ( COALESCE(folder.render_sequence, 2147483647) > criteria.cursor_render_sequence OR ( COALESCE(folder.render_sequence, 2147483647) = criteria.cursor_render_sequence AND folder.folder_id >= criteria.folder_id ) )
ORDER BY COALESCE(folder.render_sequence, 2147483647) ASC, folder.folder_id ASC LIMIT #{limit}

SELECT folder.uuid FROM folder_tb folder LEFT JOIN folder_tb parent ON folder.parent_folder_id = parent.folder_id
CROSS JOIN ( SELECT folder_id, COALESCE(render_sequence, 2147483647) AS cursor_render_sequence FROM folder_tb WHERE uuid = #{lastFolderUuid} ) criteria
parent.uuid = #{parentFolderUuid} AND resource_scope_team_id = (SELECT team_id from team_tb
uuid = #{teamUuid}
team_id = #{teamId}
) AND folder_type = #{folderType} AND folder.status = #{status}
AND ( COALESCE(folder.render_sequence, 2147483647) > criteria.cursor_render_sequence OR ( COALESCE(folder.render_sequence, 2147483647) = criteria.cursor_render_sequence AND folder.folder_id > criteria.folder_id ) )
ORDER BY COALESCE(folder.render_sequence, 2147483647) ASC, folder.folder_id ASC LIMIT #{limit}

WITH RECURSIVE folder_path AS ( SELECT folder_id, parent_folder_id, folder_name, 0 AS depth FROM folder_tb
AND uuid = #{folderUuid}
AND folder_id = #{folderId}
UNION ALL
SELECT parent.folder_id, parent.parent_folder_id, parent.folder_name, child.depth + 1 FROM folder_tb parent JOIN folder_path child ON parent.folder_id = child.parent_folder_id ) SELECT '/' || STRING_AGG(folder_name, '/' ORDER BY depth DESC) AS folder_name_path, '/' || STRING_AGG(CAST(folder_id AS VARCHAR), '/' ORDER BY depth DESC) AS folder_id_path FROM folder_path;

